def flag(parent, name):
    el=OxmlElement(name); parent.append(el)

def p(doc, text, kind=None):
    par=doc.add_paragraph(style=kind) if kind else doc.add_paragraph()
    par.alignment=WD_ALIGN_PARAGRAPH.LEFT
    par.paragraph_format.space_after=Pt(5)
    par.paragraph_format.line_spacing=1.15
    flag(par._p.get_or_add_pPr(), 'w:bidi')
    for i, part in enumerate(text.split('\n')):
        if i: par.add_run().add_break()
        run=par.add_run(part)
        flag(run._r.get_or_add_rPr(), 'w:rtl')
        run.font.name='Arial'; run.font.size=Pt(11); run.font.color.rgb=RGBColor(0,0,0)
        fonts=run._r.get_or_add_rPr().rFonts
        fonts.set(qn('w:cs'),'Arial')
        if kind: run.bold=True; run.font.size=Pt(15 if kind=='Title' else 12)
    return par

def build(name,title, sections, is_lease):
    d=Document(); sec=d.sections[0]; sec.top_margin=Cm(2); sec.bottom_margin=Cm(2); sec.left_margin=Cm(2.1); sec.right_margin=Cm(2.1)
    normal=d.styles['Normal']; normal.font.name='Arial'; normal.font.size=Pt(11)
    for style in ('Title','Heading 2'):
        d.styles[style].font.color.rgb=RGBColor(0,0,0)
        pp=d.styles[style]._element.get_or_add_pPr()
        border=pp.find(qn('w:pBdr'))
        if border is not None: pp.remove(border)
    p(d,title,'Title')
    p(d,'טיוטה לבדיקת עורך דין ורואה חשבון' if is_lease else 'טיוטה לבדיקת עורך דין', 'Heading 2')
    p(d,'טיוטה זו אינה מיועדת לחתימה לפני השלמת הפרטים ובדיקה מקצועית. תאריך: __________')
    for heading, body in [common_parties[0],common_parties[1]]+sections+common_parties[2:]:
        p(d,heading,'Heading 2'); p(d,body)
    if is_lease: p(d,'בטבלת האירועים, בעת תיקון החברה תספק ציוד חלופי בהתאם לסעיף השירות.')
    p(d,'נספח פרטי ההזמנה והחתימות','Heading 2')
    p(d,'פירוט ציוד, תעריפים, הובלה, שירות, ערוצי פנייה, פרטי ביטול ותנאים נוספים: __________\nחתימת החברה: __________\nחתימת הלקוח: __________\nתאריך: __________')
    d.save(out / (name+'.docx'))

build('computer_rental_he','הסכם שכירות ציוד מחשוב',rental,False)
build('computer_leasing_he','הסכם ליסינג ציוד מחשוב',leasing,True)
